// Where the Excel file lives: the project's output folder. n8n may only read and write there.
// Option A (Docker): keep '/data/output/Tenders.xlsx'.
// Option B (start-n8n.bat): the full path to this project's output folder, with forward slashes,
// for example 'D:/projects/tender-radar/output/Tenders.xlsx'.
return [{ json: { excel_path: '/data/output/Tenders.xlsx' } }];

// Read the partner's Decision, Reason and Outcome columns from the existing Excel file.
// No file yet (first run): carry on and create it. Any other read problem: stop, so the rebuild below
// can never overwrite decisions that were typed into the file but not saved to the database yet.
const NOT_FOUND = /ENOENT|no such file|not found|does not exist/i;
const fileItems = $('Read Excel file').all();
const fileErr = fileItems.find(i => i.json && i.json.error);
if (fileErr) {
  const msg = JSON.stringify(fileErr.json.error);
  if (!NOT_FOUND.test(msg)) {
    throw new Error(`Could not read the Excel file, so it was not rebuilt (nothing lost). Close it in Excel if it is open. Details: ${msg}`);
  }
  return [{ json: { decisions: [], ignored: [] } }];
}
// The file step finds nothing when the file does not exist yet: first run, create it.
if (!fileItems.some(i => i.binary && i.binary.data)) {
  return [{ json: { decisions: [], ignored: [] } }];
}
// The file exists, so its rows must be readable. If not, stop rather than overwrite it.
const items = $input.all();
const err = items.find(i => i.json && i.json.error);
if (err) {
  throw new Error(`Could not read the rows in the Excel file, so it was not rebuilt (nothing lost). Details: ${JSON.stringify(err.json.error)}`);
}

const DECISION = { 'go': 'go', 'no-go': 'no_go', 'no go': 'no_go', 'nogo': 'no_go', 'no_go': 'no_go' };
const OUTCOME = { 'won': 'won', 'lost': 'lost', 'not submitted': 'not_submitted', 'not_submitted': 'not_submitted' };
const clean = v => String(v ?? '').trim();

const byId = new Map();                                      // one decision per notice
const ignored = [];
for (const { json: row } of items) {
  const id = clean(row['Notice ID']);
  const rawDecision = clean(row['Decision (go / no-go)']).toLowerCase();
  const rawOutcome = clean(row['Outcome (won / lost / not submitted)']).toLowerCase();
  if (!id) {                                                 // a row without a Notice ID can't be linked to a tender
    if (rawDecision || clean(row['Reason']) || rawOutcome) ignored.push('a row with a blank Notice ID');
    continue;
  }
  if (!rawDecision) {                                        // no decision typed yet
    if (clean(row['Reason']) || rawOutcome) ignored.push(`${id} (Reason or Outcome without a Decision)`);
    continue;
  }
  const decision = DECISION[rawDecision];
  const outcome = rawOutcome ? OUTCOME[rawOutcome] : null;
  if (!decision || (rawOutcome && !outcome)) { ignored.push(`${id} (Decision or Outcome not recognised)`); continue; }
  const entry = { source_id: id, decision, reason: clean(row['Reason']), outcome };
  const prev = byId.get(id);
  if (prev && JSON.stringify(prev) !== JSON.stringify(entry)) { ignored.push(`${id} (appears twice with different values)`); continue; }
  byId.set(id, entry);
}
// Rebuilding the file would erase what could not be saved, so stop and leave the file as it is.
if (ignored.length) {
  throw new Error(`Some rows in the Excel file could not be saved, so the file was not rebuilt (nothing lost). Fix these rows and run again: ${ignored.join('; ')}. Decision: go or no-go. Outcome: won, lost or not submitted.`);
}
return [{ json: { decisions: [...byId.values()], ignored } }];

// One row per tender, in the order a partner reads it: verdict first, then what to do by when.
const VERDICT = { go: 'GO', conditional_go: 'CONDITIONAL', unresolved: 'CHECK YOURSELF', no_go: 'NO-GO' };
const TYPE = { 'cn-standard': 'Tender', 'cn-desg': 'Design contest', 'cn-social': 'Tender (light regime)' };
const DECISION = { go: 'go', no_go: 'no-go' };
const OUTCOME = { won: 'won', lost: 'lost', not_submitted: 'not submitted' };
const day = d => (d ? new Date(d).toISOString().slice(0, 10) : '');
// TED titles start with the country ("Germany – ..."); the Country column already says it.
const COUNTRY_NAME = { DE: 'Germany', DK: 'Denmark', SE: 'Sweden', NO: 'Norway' };
const stripCountry = (title, code) => {
  const name = COUNTRY_NAME[code];
  return name ? String(title ?? '').replace(new RegExp(`^${name}\\s*[–-]\\s*`), '') : (title ?? '');
};
// After the country, TED titles repeat the category ("Architectural services for buildings – "). The project name follows it.
const stripCategory = title => { const i = title.indexOf(' – '); return i > 0 && i < 70 ? title.slice(i + 3) : title; };
const today = new Date(new Date().toISOString().slice(0, 10));

return $input.all().map(({ json: t }) => {
  const deadline = day(t.deadline);
  const requests = [].concat(t.request_deadlines ?? []).map(d => String(d).slice(0, 10));
  const firstStep = !deadline ? 'Not stated: check notice'
    : requests.includes(deadline) ? 'Request to participate' : 'Submit tender';
  const daysLeft = deadline ? Math.round((new Date(deadline) - today) / 86400000) : '';
  return { json: {
    'Verdict': VERDICT[t.recommendation] ?? (t.status === 'failed' ? 'Assessment failed: check notice' : 'Not assessed yet'),
    // Older assessments said "Price weighs X%"; show them in today's wording without paying for a new assessment.
    'Why': String(t.explanation ?? '').replace(/Price weighs (\d+)%/, (m, x) => (+x >= 100 ? 'Lowest price wins (price is 100% of the score)' : `Price is ${x}% of the score`)),
    'Also required': [].concat(t.open_questions ?? []).join('; '),
    'First step': firstStep,
    'Deadline': deadline,
    'Days left': daysLeft === '' ? '' : (daysLeft < 0 ? 'closed' : daysLeft),
    'Added on': day(t.first_seen_at),
    'Title': stripCategory(stripCountry(t.title, t.country)),
    'Buyer': t.buyer ?? '',
    'Country': t.country ?? '',
    'Type': TYPE[t.notice_type] ?? (t.notice_type ?? ''),
    'Link': t.url ?? '',
    'Decision (go / no-go)': DECISION[t.decision] ?? '',
    'Reason': t.reason ?? '',
    'Outcome (won / lost / not submitted)': OUTCOME[t.outcome] ?? '',
    'Notice ID': t.source_id,
  } };
});

// Build the Excel file in plain code, so it opens readable: column widths, wrapped text, a frozen header row,
// a filter on every column, coloured verdicts and a clickable link. No library needed: an .xlsx file is a zip of XML files.
const rows = $input.all().map(i => i.json);
// Second sheet: the practice's reference projects, so "R01" in the Why can be looked up.
const refs = $('Load tender list').first()?.json.refs ?? [];
const REF_COLS = [['ID', 6], ['Name', 30], ['Type', 18], ['Country', 8], ['Year', 7], ['Size m²', 9], ['Construction cost €m', 12]];
const COLS = [
  ['Verdict', 16], ['Why', 60], ['Also required', 45], ['First step', 22], ['Deadline', 11], ['Days left', 9], ['Added on', 11], ['Title', 50],
  ['Buyer', 28], ['Country', 8], ['Type', 14], ['Link', 12], ['Decision (go / no-go)', 14], ['Reason', 30],
  ['Outcome (won / lost / not submitted)', 16], ['Notice ID', 14],
];
const WRAP = new Set(['Why', 'Also required', 'Title', 'Buyer', 'Reason']);
const VERDICT_STYLE = { 'GO': 3, 'CONDITIONAL': 4, 'CHECK YOURSELF': 5, 'NO-GO': 6 };   // style ids, see styles below

const esc = v => String(v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;')
  .replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F]/g, '');
const colName = i => (i < 26 ? String.fromCharCode(65 + i) : 'A' + String.fromCharCode(39 + i));
const cell = (ref, v, style) => {
  const s = style ? ` s="${style}"` : '';
  if (v === '' || v == null) return style ? `<c r="${ref}"${s}/>` : '';
  if (typeof v === 'number') return `<c r="${ref}"${s}><v>${v}</v></c>`;
  return `<c r="${ref}"${s} t="inlineStr"><is><t xml:space="preserve">${esc(v)}</t></is></c>`;
};
const sheetRows = [`<row r="1">${COLS.map(([h], c) => cell(`${colName(c)}1`, h, 1)).join('')}</row>`];
rows.forEach((r, i) => {
  const n = i + 2;
  sheetRows.push(`<row r="${n}">${COLS.map(([h], c) => {
    const ref = `${colName(c)}${n}`;
    const v = r[h];
    if (h === 'Link' && v) return `<c r="${ref}" s="7" t="str"><f>HYPERLINK("${esc(String(v).replace(/"/g, '""'))}","Open notice")</f><v>Open notice</v></c>`;
    if (h === 'Verdict') return cell(ref, v, VERDICT_STYLE[v] ?? 2);
    return cell(ref, v, WRAP.has(h) ? 2 : 0);
  }).join('')}</row>`);
});
const last = `${colName(COLS.length - 1)}${rows.length + 1}`;
const sheet = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships">
<sheetViews><sheetView workbookViewId="0"><pane ySplit="1" topLeftCell="A2" activePane="bottomLeft" state="frozen"/></sheetView></sheetViews>
<cols>${COLS.map(([, w], c) => `<col min="${c + 1}" max="${c + 1}" width="${w}" customWidth="1"/>`).join('')}</cols>
<sheetData>${sheetRows.join('')}</sheetData>
<autoFilter ref="A1:${last}"/>
</worksheet>`;
const refRows = [`<row r="1">${REF_COLS.map(([h], c) => cell(`${colName(c)}1`, h, 1)).join('')}</row>`];
refs.forEach((p, i) => {
  const vals = [p.id, p.name, String(p.typology).replace(/_/g, ' '), p.country, p.year == null ? '' : Number(p.year),
    p.size_m2 == null ? '' : Number(p.size_m2), p.budget_eur_m == null ? '' : Number(p.budget_eur_m)];
  refRows.push(`<row r="${i + 2}">${vals.map((v, c) => cell(`${colName(c)}${i + 2}`, v, 0)).join('')}</row>`);
});
const sheet2 = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main">
<sheetViews><sheetView workbookViewId="0"><pane ySplit="1" topLeftCell="A2" activePane="bottomLeft" state="frozen"/></sheetView></sheetViews>
<cols>${REF_COLS.map(([, w], c) => `<col min="${c + 1}" max="${c + 1}" width="${w}" customWidth="1"/>`).join('')}</cols>
<sheetData>${refRows.join('')}</sheetData>
</worksheet>`;
const fill = rgb => `<fill><patternFill patternType="solid"><fgColor rgb="FF${rgb}"/><bgColor indexed="64"/></patternFill></fill>`;
const styles = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main">
<fonts count="3"><font><sz val="11"/><name val="Calibri"/></font><font><b/><sz val="11"/><name val="Calibri"/></font><font><u/><sz val="11"/><color rgb="FF0563C1"/><name val="Calibri"/></font></fonts>
<fills count="7"><fill><patternFill patternType="none"/></fill><fill><patternFill patternType="gray125"/></fill>${fill('D9D9D9')}${fill('C6EFCE')}${fill('FFEB9C')}${fill('DDEBF7')}${fill('F2F2F2')}</fills>
<borders count="1"><border><left/><right/><top/><bottom/><diagonal/></border></borders>
<cellStyleXfs count="1"><xf numFmtId="0" fontId="0" fillId="0" borderId="0"/></cellStyleXfs>
<cellXfs count="8">
<xf numFmtId="0" fontId="0" fillId="0" borderId="0" xfId="0" applyAlignment="1"><alignment vertical="top"/></xf>
<xf numFmtId="0" fontId="1" fillId="2" borderId="0" xfId="0" applyFont="1" applyFill="1" applyAlignment="1"><alignment vertical="top" wrapText="1"/></xf>
<xf numFmtId="0" fontId="0" fillId="0" borderId="0" xfId="0" applyAlignment="1"><alignment vertical="top" wrapText="1"/></xf>
<xf numFmtId="0" fontId="1" fillId="3" borderId="0" xfId="0" applyFont="1" applyFill="1" applyAlignment="1"><alignment vertical="top"/></xf>
<xf numFmtId="0" fontId="1" fillId="4" borderId="0" xfId="0" applyFont="1" applyFill="1" applyAlignment="1"><alignment vertical="top"/></xf>
<xf numFmtId="0" fontId="1" fillId="5" borderId="0" xfId="0" applyFont="1" applyFill="1" applyAlignment="1"><alignment vertical="top"/></xf>
<xf numFmtId="0" fontId="0" fillId="6" borderId="0" xfId="0" applyFill="1" applyAlignment="1"><alignment vertical="top"/></xf>
<xf numFmtId="0" fontId="2" fillId="0" borderId="0" xfId="0" applyFont="1" applyAlignment="1"><alignment vertical="top"/></xf>
</cellXfs>
<cellStyles count="1"><cellStyle name="Normal" xfId="0" builtinId="0"/></cellStyles>
</styleSheet>`;
const files = {
  '[Content_Types].xml': `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/><Override PartName="/xl/worksheets/sheet2.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/><Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/></Types>`,
  '_rels/.rels': `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>`,
  'xl/workbook.xml': `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="Tenders" sheetId="1" r:id="rId1"/><sheet name="Reference projects" sheetId="2" r:id="rId3"/></sheets><definedNames><definedName name="_xlnm._FilterDatabase" localSheetId="0" hidden="1">Tenders!$A$1:$${last.replace(/(\d+)$/, '$$$1')}</definedName></definedNames></workbook>`,
  'xl/_rels/workbook.xml.rels': `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/><Relationship Id="rId2" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/><Relationship Id="rId3" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet2.xml"/></Relationships>`,
  'xl/worksheets/sheet1.xml': sheet,
  'xl/worksheets/sheet2.xml': sheet2,
  'xl/styles.xml': styles,
};

// Zip without compression ("stored"): valid for Excel, and needs no library.
const CRC = Array.from({ length: 256 }, (_, n) => { let c = n; for (let k = 0; k < 8; k++) c = c & 1 ? 0xEDB88320 ^ (c >>> 1) : c >>> 1; return c >>> 0; });
const crc32 = b => { let c = 0xFFFFFFFF; for (const x of b) c = CRC[(c ^ x) & 0xFF] ^ (c >>> 8); return (c ^ 0xFFFFFFFF) >>> 0; };
const parts = [];
const central = [];
let offset = 0;
for (const [name, text] of Object.entries(files)) {
  const data = Buffer.from(text, 'utf8');
  const nameBuf = Buffer.from(name, 'utf8');
  const crc = crc32(data);
  const local = Buffer.alloc(30);
  local.writeUInt32LE(0x04034b50, 0); local.writeUInt16LE(20, 4); local.writeUInt16LE(0x0800, 6); local.writeUInt16LE(0, 8);
  local.writeUInt32LE(0, 10); local.writeUInt32LE(crc, 14); local.writeUInt32LE(data.length, 18); local.writeUInt32LE(data.length, 22);
  local.writeUInt16LE(nameBuf.length, 26); local.writeUInt16LE(0, 28);
  const dir = Buffer.alloc(46);
  dir.writeUInt32LE(0x02014b50, 0); dir.writeUInt16LE(20, 4); dir.writeUInt16LE(20, 6); dir.writeUInt16LE(0x0800, 8); dir.writeUInt16LE(0, 10);
  dir.writeUInt32LE(0, 12); dir.writeUInt32LE(crc, 16); dir.writeUInt32LE(data.length, 20); dir.writeUInt32LE(data.length, 24);
  dir.writeUInt16LE(nameBuf.length, 28); dir.writeUInt32LE(offset, 42);
  parts.push(local, nameBuf, data);
  central.push(dir, nameBuf);
  offset += 30 + nameBuf.length + data.length;
}
const centralBuf = Buffer.concat(central);
const end = Buffer.alloc(22);
end.writeUInt32LE(0x06054b50, 0); end.writeUInt16LE(Object.keys(files).length, 8); end.writeUInt16LE(Object.keys(files).length, 10);
end.writeUInt32LE(centralBuf.length, 12); end.writeUInt32LE(offset, 16);
const zip = Buffer.concat([...parts, centralBuf, end]);

return [{ json: { rows: rows.length }, binary: { data: {
  data: zip.toString('base64'), mimeType: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
  fileExtension: 'xlsx', fileName: 'Tenders.xlsx',
} } }];
